import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
const expectedRepo='ajay1980-hue/Packsmart-hub';
const input=JSON.parse(fs.readFileSync('.github/ci/renewal/inputs.json','utf8'));
const event=JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH,'utf8'));
const pr=event.pull_request;
assert.equal(process.env.GITHUB_EVENT_NAME,'pull_request');assert.equal(event.action,'ready_for_review');
assert.equal(process.env.GITHUB_REPOSITORY,expectedRepo);assert.equal(event.repository.full_name,expectedRepo);
assert.equal(pr.base.repo.full_name,expectedRepo);assert.equal(pr.head.repo.full_name,expectedRepo);assert.equal(pr.base.ref,'main');
const approved={base:process.env.REVIEWED_BASE_SHA,head:process.env.REVIEWED_HEAD_SHA,merge:process.env.REVIEWED_MERGE_SHA,pr:process.env.REVIEWED_PR_NUMBER};
for(const key of ['base','head','merge'])assert.match(approved[key]||'',/^[a-f0-9]{40}$/,'HOLD: exact independently reviewed SHA missing');
assert.match(approved.pr||'',/^[1-9][0-9]*$/);assert.equal(String(pr.number),approved.pr);
assert.equal(approved.base,input.sourceBaseCommit);assert.equal(pr.base.sha,approved.base);assert.equal(pr.head.sha,approved.head);
assert.equal(pr.merge_commit_sha,approved.merge);assert.equal(process.env.GITHUB_SHA,approved.merge);
const git=(...args)=>execFileSync('git',args,{encoding:'utf8'}).trim();
assert.equal(git('rev-parse','HEAD'),approved.merge);
assert.deepEqual(git('rev-list','--parents','-n','1','HEAD').split(' '),[approved.merge,approved.base,approved.head]);
assert.equal(git('status','--porcelain','--untracked-files=all'),'','qualification must begin from a clean checkout');
const id=process.env.RUNVARA_QUALIFICATION_ID;assert.match(id||'',/^[0-9]+-1$/);
const folder=path.resolve('.runvara-qualification',id,'evidence');fs.mkdirSync(folder,{recursive:true});
fs.writeFileSync(path.join(folder,'reviewed-source.json'),JSON.stringify({repository:expectedRepo,pr:Number(approved.pr),base:approved.base,head:approved.head,merge:approved.merge,event:'ready_for_review',runId:process.env.GITHUB_RUN_ID,runAttempt:1,globalOnceGuaranteed:false},null,2),{flag:'wx'});
